export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let initialized = false;
  let prevPos = { x: 0, y: 0, z: 0 };
  let prevVel = { x: 0, y: 0, z: 0 };
  let prevAtt = { roll: 0, pitch: 0, yaw: 0 };
  let prevRates = { roll: 0, pitch: 0, yaw: 0 };
  let prevDir = { x: 0, y: 1, z: 0 };
  let lastAction = { thrust: 0.5, roll: 0, pitch: 0, yawRate: 0 };

  let simInt = { roll: 0, pitch: 0 };
  let uThrust = 0;
  let uAlpha = { roll: 0, pitch: 0, yaw: 0 };

  let biasPerThrust = { roll: 0, pitch: 0, yaw: 0 };
  let biasResid = { roll: 0, pitch: 0, yaw: 0 };

  let thrustScale = 20.5;
  let filtAy = 0, filtUy = 0.5, filtVy = 0;
  let intY = 0;

  let windFast = { x: 0, z: 0 };
  let windSlow = { x: 0, z: 0 };

  let gateIdx = -1;
  let phase = 'align';
  let centeredCount = 0;
  let padPhase = 'approach';

  function getDir(att) {
    const bx = Math.sin(att.pitch) * Math.cos(att.roll);
    const bz = -Math.sin(att.roll);
    const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
    return {
      x: cy * bx + sy * bz,
      y: Math.cos(att.pitch) * Math.cos(att.roll),
      z: -sy * bx + cy * bz,
    };
  }

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;
      const dir = getDir(att);

      if (!initialized) {
        initialized = true;
        prevPos = { ...p };
        prevVel = { ...v };
        prevAtt = { ...att };
        prevRates = { ...rates };
        prevDir = { ...dir };
      } else {
        const alphaM = 1 - Math.exp(-0.005 / 0.038);
        const cmdAlpha = { roll: 0, pitch: 0, yaw: 0 };
        for (const axis of ['roll', 'pitch']) {
          const e1 = lastAction[axis] - prevAtt[axis];
          simInt[axis] = clamp(simInt[axis] + e1 * 0.005, -0.35, 0.35);
          const a1 = 65 * e1 - 13 * prevRates[axis] + 22 * simInt[axis];
          uAlpha[axis] += (a1 - uAlpha[axis]) * alphaM;
          uThrust += (lastAction.thrust - uThrust) * (alphaM * 0.5);

          const midAtt = 0.5 * (prevAtt[axis] + att[axis]);
          const midRate = 0.5 * (prevRates[axis] + rates[axis]);
          const e2 = lastAction[axis] - midAtt;
          simInt[axis] = clamp(simInt[axis] + e2 * 0.005, -0.35, 0.35);
          const a2 = 65 * e2 - 13 * midRate + 22 * simInt[axis];
          uAlpha[axis] += (a2 - uAlpha[axis]) * alphaM;
          uThrust += (lastAction.thrust - uThrust) * (alphaM * 0.5);
          cmdAlpha[axis] = uAlpha[axis];
        }
        const ay1 = 8 * (lastAction.yawRate - prevRates.yaw);
        uAlpha.yaw += (ay1 - uAlpha.yaw) * alphaM;
        const ay2 = 8 * (lastAction.yawRate - 0.5 * (prevRates.yaw + rates.yaw));
        uAlpha.yaw += (ay2 - uAlpha.yaw) * alphaM;

        if (p.y > 0.09) {
          for (const axis of ['roll', 'pitch', 'yaw']) {
            const midRate = 0.5 * (prevRates[axis] + rates[axis]);
            const measAlpha = (rates[axis] - prevRates[axis]) / dt + 0.4 * midRate;
            const dist = measAlpha - uAlpha[axis];
            const pred = biasPerThrust[axis] * uThrust + biasResid[axis];
            const err = clamp(dist - pred, -30, 30);
            if (uThrust > 0.2) {
              biasPerThrust[axis] = clamp(biasPerThrust[axis] + 0.14 * err * uThrust, -35, 35);
            }
            biasResid[axis] = clamp(biasResid[axis] + 0.22 * err, -18, 18);
          }

          const dragCoeff = 0.0275 * thrustScale;
          const measAy = (v.y - prevVel.y) / dt;
          const uy = uThrust * 0.5 * (prevDir.y + dir.y);
          const vy = 0.5 * (prevVel.y + v.y);
          filtAy += 0.18 * (measAy - filtAy);
          filtUy += 0.18 * (uy - filtUy);
          filtVy += 0.18 * (vy - filtVy);
          if (filtUy > 0.25 && obs.t > 0.06) {
            const errAy = (filtAy + 9.81 + dragCoeff * filtVy) - thrustScale * filtUy;
            thrustScale = clamp(thrustScale + 0.16 * (errAy / filtUy), 14.5, 27.5);
          }

          const ux = uThrust * 0.5 * (prevDir.x + dir.x);
          const uz = uThrust * 0.5 * (prevDir.z + dir.z);
          const vx = 0.5 * (prevVel.x + v.x);
          const vz = 0.5 * (prevVel.z + v.z);
          const measAx = (v.x - prevVel.x) / dt;
          const measAz = (v.z - prevVel.z) / dt;
          const rawWx = clamp(measAx + dragCoeff * vx - thrustScale * ux, -15, 15);
          const rawWz = clamp(measAz + dragCoeff * vz - thrustScale * uz, -15, 15);

          windFast.x += 0.28 * (rawWx - windFast.x);
          windFast.z += 0.28 * (rawWz - windFast.z);
          windSlow.x += 0.03 * (rawWx - windSlow.x);
          windSlow.z += 0.03 * (rawWz - windSlow.z);
        }
      }

      const gustDx = windFast.x - windSlow.x;
      const gustDz = windFast.z - windSlow.z;
      const gustMag = Math.hypot(gustDx, gustDz);

      let target = { x: p.x, y: 1.0, z: p.z };
      let targetVel = { x: 0, y: 0, z: 0 };
      let kpX = 6.0, kdX = 4.2, kpZ = 7.5, kdZ = 4.8;
      let kpY = 7.5, kdY = 4.5;
      let maxTilt = 0.52;
      let pinPad = false;

      if (obs.gateIndex < 3) {
        const g = obs.nextGate.centre;
        if (gateIdx !== obs.gateIndex) {
          gateIdx = obs.gateIndex;
          phase = 'align';
          centeredCount = 0;
        }

        const dx = g.x - p.x;
        const dy = g.y - p.y;
        const dz = g.z - p.z;
        const tCross = clamp(dx / Math.max(0.35, v.x), 0.04, 0.35);
        const predY = p.y + v.y * tCross;
        const predZ = p.z + v.z * tCross;
        const errY = Math.abs(g.y - p.y);
        const errZ = Math.abs(g.z - p.z);
        const predErrY = Math.abs(g.y - predY);
        const predErrZ = Math.abs(g.z - predZ);

        if (phase === 'align') {
          const alignDist = 0.32;
          target = { x: g.x - alignDist, y: g.y, z: g.z };
          kpZ = 9.5; kdZ = 5.4;
          kpY = 8.5; kdY = 4.8;
          kpX = 6.5; kdX = 4.5;

          const xReady = p.x > g.x - 0.55 && p.x < g.x - 0.12 && Math.abs(v.x) < 0.65;
          const yzCentered = errZ < 0.018 && predErrZ < 0.022 && Math.abs(v.z) < 0.16 &&
                             errY < 0.065 && predErrY < 0.08 && Math.abs(v.y) < 0.35;
          if (xReady && yzCentered && gustMag < 2.2) {
            centeredCount++;
          } else {
            centeredCount = Math.max(0, centeredCount - 1);
          }
          if (centeredCount >= 4) {
            phase = 'lunge';
          }
          // Prevent accidental premature crossing if not centered
          if (p.x + v.x * 0.12 > g.x - 0.08 && (errZ > 0.024 || errY > 0.10)) {
