            kpX = 9.0; kdX = 6.0;
          }
        }

        if (phase === 'lunge') {
          // Abort lunge if still able to stop and blown off center
          if (p.x < g.x - 0.14 && (predErrZ > 0.028 || errZ > 0.026 || predErrY > 0.11)) {
            phase = 'align';
            centeredCount = 0;
            target = { x: g.x - 0.34, y: g.y, z: g.z };
            kpX = 9.5; kdX = 6.2;
          } else {
            target = { x: g.x + 0.32, y: g.y, z: g.z };
            targetVel.x = 1.35;
            kpX = 7.5; kdX = 4.2;
            kpZ = 11.5; kdZ = 6.0;
            kpY = 9.5; kdY = 5.2;
          }
        }
      } else {
        const pad = obs.pad.centre;
        const distXZ = Math.hypot(pad.x - p.x, pad.z - p.z);
        const speedXZ = Math.hypot(v.x, v.z);
        const speed = Math.hypot(v.x, v.y, v.z);

        if (padPhase === 'approach') {
          target = { x: pad.x, y: 0.42, z: pad.z };
          if (distXZ > 0.45) {
            target.y = Math.max(0.45, Math.min(0.95, p.y));
          }
          kpX = 6.8; kdX = 4.6;
          kpZ = 6.8; kdZ = 4.6;
          if (distXZ < 0.11 && speedXZ < 0.28 && p.y < 0.55) {
            padPhase = 'descend';
          }
        }

        if (padPhase === 'descend') {
          target = { x: pad.x, y: 0.05, z: pad.z };
          targetVel.y = -0.35;
          kpX = 8.0; kdX = 5.2;
          kpZ = 8.0; kdZ = 5.2;
          kpY = 6.5; kdY = 4.8;
          maxTilt = 0.28;
          if (distXZ > 0.145 && p.y > 0.14) {
            padPhase = 'approach';
          }
          if (p.y <= 0.092 && distXZ <= 0.135 && speed < 0.48) {
            padPhase = 'pin';
          }
        }

        if (padPhase === 'pin') {
          if (distXZ > 0.145 || p.y > 0.11) {
            padPhase = 'descend';
          } else {
            pinPad = true;
          }
        }
      }

      if (pinPad) {
        const pad = obs.pad.centre;
        const axPin = clamp(3.5 * (pad.x - p.x) - 3.0 * v.x - 0.5 * windFast.x, -1.1, 1.1);
        const azPin = clamp(3.5 * (pad.z - p.z) - 3.0 * v.z - 0.5 * windFast.z, -1.1, 1.1);
        const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
        const desPitch = clamp((cy * axPin - sy * azPin) / 9.81, -0.10, 0.10);
        const desRoll = clamp(-(sy * axPin + cy * azPin) / 9.81, -0.10, 0.10);
        const pinThrust = 0.08;
        const bRoll = biasPerThrust.roll * pinThrust + biasResid.roll;
        const bPitch = biasPerThrust.pitch * pinThrust + biasResid.pitch;
        const bYaw = biasPerThrust.yaw * pinThrust + biasResid.yaw;
        const cmdRoll = clamp(desRoll - (bRoll + 22 * simInt.roll + 2.5 * rates.roll) / 65, -0.16, 0.16);
        const cmdPitch = clamp(desPitch - (bPitch + 22 * simInt.pitch + 2.5 * rates.pitch) / 65, -0.16, 0.16);
        const cmdYawRate = clamp(rates.yaw + (-10 * att.yaw - 3.5 * rates.yaw - bYaw) / 8, -2, 2);

        lastAction = { thrust: pinThrust, roll: cmdRoll, pitch: cmdPitch, yawRate: cmdYawRate };
        prevPos = { ...p }; prevVel = { ...v }; prevAtt = { ...att }; prevRates = { ...rates }; prevDir = { ...dir };
        return lastAction;
      }

      const dragCoeff = 0.0275 * thrustScale;
      const windCompX = windFast.x + 0.18 * gustDx;
      const windCompZ = windFast.z + 0.18 * gustDz;

      // Brake gusts: extra velocity damping when gust transient is strong
      const gustBrake = clamp(gustMag * 0.35, 0, 1.8);

      let ax = kpX * (target.x - p.x) + (kdX + gustBrake) * (targetVel.x - v.x) + dragCoeff * v.x - windCompX;
      let az = kpZ * (target.z - p.z) + (kdZ + gustBrake) * (targetVel.z - v.z) + dragCoeff * v.z - windCompZ;

      // Never allow backward crossing of an already-passed gate plane
      if (obs.gateIndex > 0) {
        const prevGateX = obs.gateIndex === 1 ? -1.15 : (obs.gateIndex === 2 ? 0.15 : 1.35);
        if (p.x < prevGateX + 0.18 && v.x < 0.2) {
          ax = Math.max(ax, 4.0 * (prevGateX + 0.22 - p.x) - 5.0 * v.x);
        }
      }

      const ey = target.y - p.y;
      intY = clamp(intY + ey * dt, -0.6, 0.6);
      const ay = clamp(kpY * ey + kdY * (targetVel.y - v.y) + 1.8 * intY + dragCoeff * v.y, -5.0, 6.5);

      const totalAy = Math.max(2.0, 9.81 + ay);
      const maxAccXZ = totalAy * Math.tan(maxTilt);
      const accXZ = Math.hypot(ax, az);
      if (accXZ > maxAccXZ) {
        const s = maxAccXZ / accXZ;
        ax *= s;
        az *= s;
      }

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyAx = cy * ax - sy * az;
      const bodyAz = -sy * ax - cy * az;

      const desPitch = clamp(Math.atan2(bodyAx, totalAy), -maxTilt, maxTilt);
      const desRoll = clamp(Math.atan2(-bodyAz * Math.cos(desPitch), totalAy), -maxTilt, maxTilt);

      const tiltCos = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      const rawThrust = clamp(totalAy / (thrustScale * tiltCos), 0.05, 1.0);
      // Lead filter for motor lag
      const thrust = clamp(rawThrust + 0.25 * (rawThrust - uThrust), 0.05, 1.0);

      const estUThrust = 0.7 * uThrust + 0.3 * thrust;
      const bRoll = biasPerThrust.roll * estUThrust + biasResid.roll;
      const bPitch = biasPerThrust.pitch * estUThrust + biasResid.pitch;
      const bYaw = biasPerThrust.yaw * estUThrust + biasResid.yaw;

      const cmdRoll = clamp(desRoll - (bRoll + 22 * simInt.roll + 3.0 * rates.roll) / 65, -0.6, 0.6);
      const cmdPitch = clamp(desPitch - (bPitch + 22 * simInt.pitch + 3.0 * rates.pitch) / 65, -0.6, 0.6);
      const cmdYawRate = clamp(rates.yaw + (-12 * att.yaw - 4.0 * rates.yaw - bYaw) / 8, -2, 2);

      lastAction = { thrust, roll: cmdRoll, pitch: cmdPitch, yawRate: cmdYawRate };
      prevPos = { ...p };
      prevVel = { ...v };
      prevAtt = { ...att };
      prevRates = { ...rates };
      prevDir = { ...dir };
      return lastAction;
    },
  };
}

export default function makeController() {
