        const cmdPitch = clamp(desPitch - (bPitch + 22 * simInt.pitch + 2.5 * rates.pitch) / 65, -0.16, 0.16);
        const cmdYawRate = clamp(rates.yaw + (-10 * att.yaw - 3.5 * rates.yaw - bYaw) / 8, -2, 2);

        lastAction = { thrust: pinThrust, roll: cmdRoll, pitch: cmdPitch, yawRate: cmdYawRate };
        prevPos = { ...p }; prevVel = { ...v }; prevAtt = { ...att }; prevRates = { ...rates }; prevDir = { ...dir };
        return lastAction;
      }

      const dragCoeff = 0.0275 * thrustScale;
      const windCompX = windFast.x + 0.18 * gustDx;
      const windCompZ = windFast.z + 0.18 * gustDz;
      const gustBrake = clamp(gustMag * 0.35, 0, 1.8);

      let ax = kpX * (target.x - p.x) + (kdX + gustBrake) * (targetVel.x - v.x) + dragCoeff * v.x - windCompX;
      let az = kpZ * (target.z - p.z) + (kdZ + gustBrake) * (targetVel.z - v.z) + dragCoeff * v.z - windCompZ;

      if (obs.gateIndex > 0) {
        const prevGateX = obs.gateIndex === 1 ? -1.15 : (obs.gateIndex === 2 ? 0.15 : 1.35);
        if (p.x < prevGateX + 0.18 && v.x < 0.2) {
          ax = Math.max(ax, 4.0 * (prevGateX + 0.22 - p.x) - 5.0 * v.x);
        }
      }

      const ey = target.y - p.y;
      intY = clamp(intY + ey * dt, -0.6, 0.6);
      const ay = clamp(kpY * ey + kdY * (targetVel.y - v.y) + 1.8 * intY + dragCoeff * v.y, -5.0, 6.5);

      const totalAy = Math.max(2.0, 9.81 + ay);
      const maxAccXZ = totalAy * Math.tan(maxTilt);
      const accXZ = Math.hypot(ax, az);
      if (accXZ > maxAccXZ) {
        const s = maxAccXZ / accXZ;
        ax *= s;
        az *= s;
      }

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyAx = cy * ax - sy * az;
      const bodyAz = -sy * ax - cy * az;

      const desPitch = clamp(Math.atan2(bodyAx, totalAy), -maxTilt, maxTilt);
      const desRoll = clamp(Math.atan2(-bodyAz * Math.cos(desPitch), totalAy), -maxTilt, maxTilt);

      const tiltCos = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      const rawThrust = clamp(totalAy / (thrustScale * tiltCos), 0.05, 1.0);
      const thrust = clamp(rawThrust + 0.25 * (rawThrust - uThrust), 0.05, 1.0);

      const estUThrust = 0.7 * uThrust + 0.3 * thrust;
      const bRoll = biasPerThrust.roll * estUThrust + biasResid.roll;
      const bPitch = biasPerThrust.pitch * estUThrust + biasResid.pitch;
      const bYaw = biasPerThrust.yaw * estUThrust + biasResid.yaw;

      const cmdRoll = clamp(desRoll - (bRoll + 22 * simInt.roll + 3.0 * rates.roll) / 65, -0.6, 0.6);
      const cmdPitch = clamp(desPitch - (bPitch + 22 * simInt.pitch + 3.0 * rates.pitch) / 65, -0.6, 0.6);
      const cmdYawRate = clamp(rates.yaw + (-12 * att.yaw - 4.0 * rates.yaw - bYaw) / 8, -2, 2);

      lastAction = { thrust, roll: cmdRoll, pitch: cmdPitch, yawRate: cmdYawRate };
      prevPos = { ...p };
      prevVel = { ...v };
      prevAtt = { ...att };
      prevRates = { ...rates };
      prevDir = { ...dir };
      return lastAction;
    },
  };
}

export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let initialized = false;
  let prevPos = { x: 0, y: 0, z: 0 };
  let prevVel = { x: 0, y: 0, z: 0 };
  let prevAtt = { roll: 0, pitch: 0, yaw: 0 };
  let prevRates = { roll: 0, pitch: 0, yaw: 0 };
  let prevDir = { x: 0, y: 1, z: 0 };
  let lastAction = { thrust: 0.5, roll: 0, pitch: 0, yawRate: 0 };

  let simInt = { roll: 0, pitch: 0 };
  let uThrust = 0;
  let uAlpha = { roll: 0, pitch: 0, yaw: 0 };

  let biasPerThrust = { roll: 0, pitch: 0, yaw: 0 };
  let biasResid = { roll: 0, pitch: 0, yaw: 0 };

  let thrustScale = 20.5;
  let filtAy = 0, filtUy = 0.5, filtVy = 0;
  let intY = 0;

  let windFast = { x: 0, z: 0 };
  let windSlow = { x: 0, z: 0 };

  let gateIdx = -1;
  let phase = 'align';
  let centeredCount = 0;
  let padPhase = 'approach';

  function getDir(att) {
    const bx = Math.sin(att.pitch) * Math.cos(att.roll);
    const bz = -Math.sin(att.roll);
    const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
    return {
      x: cy * bx + sy * bz,
      y: Math.cos(att.pitch) * Math.cos(att.roll),
      z: -sy * bx + cy * bz,
    };
  }

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;
      const dir = getDir(att);

      if (!initialized) {
        initialized = true;
        prevPos = { ...p };
        prevVel = { ...v };
        prevAtt = { ...att };
        prevRates = { ...rates };
        prevDir = { ...dir };
      } else {
        const alphaM = 1 - Math.exp(-0.005 / 0.038);
        const uThrust1 = uThrust + (lastAction.thrust - uThrust) * alphaM;
        const uThrust2 = uThrust1 + (lastAction.thrust - uThrust1) * alphaM;
        const effUThrust = 0.5 * (uThrust1 + uThrust2);
        uThrust = uThrust2;

        const effUAlpha = { roll: 0, pitch: 0, yaw: 0 };
        for (const axis of ['roll', 'pitch']) {
          const e1 = lastAction[axis] - prevAtt[axis];
          simInt[axis] = clamp(simInt[axis] + e1 * 0.005, -0.35, 0.35);
          const a1 = 65 * e1 - 13 * prevRates[axis] + 22 * simInt[axis];
          const ua1 = uAlpha[axis] + (a1 - uAlpha[axis]) * alphaM;

          const midAtt = 0.5 * (prevAtt[axis] + att[axis]);
          const midRate = 0.5 * (prevRates[axis] + rates[axis]);
          const e2 = lastAction[axis] - midAtt;
          simInt[axis] = clamp(simInt[axis] + e2 * 0.005, -0.35, 0.35);
          const a2 = 65 * e2 - 13 * midRate + 22 * simInt[axis];
          const ua2 = ua1 + (a2 - ua1) * alphaM;

          effUAlpha[axis] = 0.5 * (ua1 + ua2);
          uAlpha[axis] = ua2;
        }
        const ay1 = 8 * (lastAction.yawRate - prevRates.yaw);
        const uay1 = uAlpha.yaw + (ay1 - uAlpha.yaw) * alphaM;
        const ay2 = 8 * (lastAction.yawRate - 0.5 * (prevRates.yaw + rates.yaw));
        const uay2 = uay1 + (ay2 - uay1) * alphaM;
        effUAlpha.yaw = 0.5 * (uay1 + uay2);
        uAlpha.yaw = uay2;

        if (p.y > 0.09) {
          for (const axis of ['roll', 'pitch', 'yaw']) {
            const midRate = 0.5 * (prevRates[axis] + rates[axis]);
            const measAlpha = (rates[axis] - prevRates[axis]) / dt + 0.4 * midRate;
            const dist = measAlpha - effUAlpha[axis];
            const pred = biasPerThrust[axis] * effUThrust + biasResid[axis];
            const err = clamp(dist - pred, -30, 30);
            if (effUThrust > 0.2) {
              biasPerThrust[axis] = clamp(biasPerThrust[axis] + 0.14 * err * effUThrust, -35, 35);
            }
            biasResid[axis] = clamp(biasResid[axis] + 0.22 * err, -18, 18);
          }

          const dragCoeff = 0.0275 * thrustScale;
          const measAy = (v.y - prevVel.y) / dt;
          const uy = effUThrust * 0.5 * (prevDir.y + dir.y);
          const vy = 0.5 * (prevVel.y + v.y);
          filtAy += 0.18 * (measAy - filtAy);
          filtUy += 0.18 * (uy - filtUy);
          filtVy += 0.18 * (vy - filtVy);
          if (filtUy > 0.25 && obs.t > 0.06) {
            const errAy = (filtAy + 9.81 + dragCoeff * filtVy) - thrustScale * filtUy;
            thrustScale = clamp(thrustScale + 0.16 * (errAy / filtUy), 14.5, 27.5);
          }

          const ux = effUThrust * 0.5 * (prevDir.x + dir.x);
          const uz = effUThrust * 0.5 * (prevDir.z + dir.z);
          const vx = 0.5 * (prevVel.x + v.x);
          const vz = 0.5 * (prevVel.z + v.z);
          const measAx = (v.x - prevVel.x) / dt;
          const measAz = (v.z - prevVel.z) / dt;
          const rawWx = clamp(measAx + dragCoeff * vx - thrustScale * ux, -15, 15);
          const rawWz = clamp(measAz + dragCoeff * vz - thrustScale * uz, -15, 15);

          windFast.x += 0.28 * (rawWx - windFast.x);
          windFast.z += 0.28 * (rawWz - windFast.z);
          windSlow.x += 0.03 * (rawWx - windSlow.x);
          windSlow.z += 0.03 * (rawWz - windSlow.z);
        }
      }

      const gustDx = windFast.x - windSlow.x;
      const gustDz = windFast.z - windSlow.z;
      const gustMag = Math.hypot(gustDx, gustDz);

      let target = { x: p.x, y: 1.0, z: p.z };
      let targetVel = { x: 0, y: 0, z: 0 };
      let kpX = 6.0, kdX = 4.2, kpZ = 7.5, kdZ = 4.8;
      let kpY = 7.5, kdY = 4.5;
      let maxTilt = 0.52;
      let pinPad = false;

      if (obs.gateIndex < 3) {
        const g = obs.nextGate.centre;
        if (gateIdx !== obs.gateIndex) {
          gateIdx = obs.gateIndex;
          phase = 'align';
          centeredCount = 0;
        }

        const dx = g.x - p.x;
        const tCross = clamp(dx / Math.max(0.35, v.x), 0.04, 0.35);
        const predY = p.y + v.y * tCross;
        const predZ = p.z + v.z * tCross;
        const errY = Math.abs(g.y - p.y);
        const errZ = Math.abs(g.z - p.z);
        const predErrY = Math.abs(g.y - predY);
        const predErrZ = Math.abs(g.z - predZ);

        if (phase === 'align') {
          const alignDist = 0.32;
          target = { x: g.x - alignDist, y: g.y, z: g.z };
          kpZ = 9.5; kdZ = 5.4;
          kpY = 8.5; kdY = 4.8;
          kpX = 6.5; kdX = 4.5;

          const xReady = p.x > g.x - 0.55 && p.x < g.x - 0.12 && Math.abs(v.x) < 0.65;
          const yzCentered = errZ < 0.018 && predErrZ < 0.022 && Math.abs(v.z) < 0.16 &&
                             errY < 0.065 && predErrY < 0.08 && Math.abs(v.y) < 0.35;
          if (xReady && yzCentered && gustMag < 2.2) {
            centeredCount++;
          } else {
            centeredCount = Math.max(0, centeredCount - 1);
          }
          if (centeredCount >= 4) {
            phase = 'lunge';
          }
          if (p.x + v.x * 0.12 > g.x - 0.08 && (errZ > 0.024 || errY > 0.10)) {
            target.x = g.x - 0.38;
            kpX = 9.0; kdX = 6.0;
          }
        }

        if (phase === 'lunge') {
          if (p.x < g.x - 0.14 && (predErrZ > 0.028 || errZ > 0.026 || predErrY > 0.11)) {
            phase = 'align';
            centeredCount = 0;
            target = { x: g.x - 0.34, y: g.y, z: g.z };
            kpX = 9.5; kdX = 6.2;
          } else {
            target = { x: g.x + 0.32, y: g.y, z: g.z };
            targetVel.x = 1.35;
            kpX = 7.5; kdX = 4.2;
            kpZ = 11.5; kdZ = 6.0;
            kpY = 9.5; kdY = 5.2;
          }
        }
      } else {
        const pad = obs.pad.centre;
        const distXZ = Math.hypot(pad.x - p.x, pad.z - p.z);
        const speedXZ = Math.hypot(v.x, v.z);
        const speed = Math.hypot(v.x, v.y, v.z);

        if (padPhase === 'approach') {
          target = { x: pad.x, y: 0.42, z: pad.z };
          if (distXZ > 0.45) {
            target.y = Math.max(0.45, Math.min(0.95, p.y));
          }
          kpX = 6.8; kdX = 4.6;
          kpZ = 6.8; kdZ = 4.6;
          if (distXZ < 0.11 && speedXZ < 0.28 && p.y < 0.55) {
            padPhase = 'descend';
          }
        }

        if (padPhase === 'descend') {
          target = { x: pad.x, y: 0.05, z: pad.z };
          targetVel.y = -0.35;
          kpX = 8.0; kdX = 5.2;
          kpZ = 8.0; kdZ = 5.2;
          kpY = 6.5; kdY = 4.8;
          maxTilt = 0.28;
          if (distXZ > 0.145 && p.y > 0.14) {
            padPhase = 'approach';
          }
          if (p.y <= 0.092 && distXZ <= 0.135 && speed < 0.48) {
            padPhase = 'pin';
          }
        }

        if (padPhase === 'pin') {
          if (distXZ > 0.145 || p.y > 0.11) {
            padPhase = 'descend';
          } else {
            pinPad = true;
          }
        }
      }

      if (pinPad) {
        const pad = obs.pad.centre;
        const axPin = clamp(3.5 * (pad.x - p.x) - 3.0 * v.x - 0.5 * windFast.x, -1.1, 1.1);
        const azPin = clamp(3.5 * (pad.z - p.z) - 3.0 * v.z - 0.5 * windFast.z, -1.1, 1.1);
        const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
        const desPitch = clamp((cy * axPin - sy * azPin) / 9.81, -0.10, 0.10);
        const desRoll = clamp(-(sy * axPin + cy * azPin) / 9.81, -0.10, 0.10);
        const pinThrust = 0.08;
        const bRoll = biasPerThrust.roll * pinThrust + biasResid.roll;
        const bPitch = biasPerThrust.pitch * pinThrust + biasResid.pitch;
        const bYaw = biasPerThrust.yaw * pinThrust + biasResid.yaw;
        const cmdRoll = clamp(desRoll - (bRoll + 22 * simInt.roll + 2.5 * rates.roll) / 65, -0.16, 0.16);
        const cmdPitch = clamp(desPitch - (bPitch + 22 * simInt.pitch + 2.5 * rates.pitch) / 65, -0.16, 0.16);
        const cmdYawRate = clamp(rates.yaw + (-10 * att.yaw - 3.5 * rates.yaw - bYaw) / 8, -2, 2);

        lastAction = { thrust: pinThrust, roll: cmdRoll, pitch: cmdPitch, yawRate: cmdYawRate };
        prevPos = { ...p }; prevVel = { ...v }; prevAtt = { ...att }; prevRates = { ...rates }; prevDir = { ...dir };
        return lastAction;
      }

      const dragCoeff = 0.0275 * thrustScale;
      const windCompX = windFast.x + 0.18 * gustDx;
      const windCompZ = windFast.z + 0.18 * gustDz;
      const gustBrake = clamp(gustMag * 0.35, 0, 1.8);

      let ax = kpX * (target.x - p.x) + (kdX + gustBrake) * (targetVel.x - v.x) + dragCoeff * v.x - windCompX;
      let az = kpZ * (target.z - p.z) + (kdZ + gustBrake) * (targetVel.z - v.z) + dragCoeff * v.z - windCompZ;

      if (obs.gateIndex > 0) {
        const prevGateX = obs.gateIndex === 1 ? -1.15 : (obs.gateIndex === 2 ? 0.15 : 1.35);
        if (p.x < prevGateX + 0.18 && v.x < 0.2) {
          ax = Math.max(ax, 4.0 * (prevGateX + 0.22 - p.x) - 5.0 * v.x);
        }
      }

      const ey = target.y - p.y;
      intY = clamp(intY + ey * dt, -0.6, 0.6);
      const ay = clamp(kpY * ey + kdY * (targetVel.y - v.y) + 1.8 * intY + dragCoeff * v.y, -5.0, 6.5);

      const totalAy = Math.max(2.0, 9.81 + ay);
      const maxAccXZ = totalAy * Math.tan(maxTilt);
      const accXZ = Math.hypot(ax, az);
      if (accXZ > maxAccXZ) {
        const s = maxAccXZ / accXZ;
        ax *= s;
        az *= s;
      }

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyAx = cy * ax - sy * az;
      const bodyAz = sy * ax + cy * az;

      const desPitch = clamp(Math.atan2(bodyAx, totalAy), -maxTilt, maxTilt);
      const desRoll = clamp(Math.atan2(-bodyAz, Math.hypot(bodyAx, totalAy)), -maxTilt, maxTilt);

      const tiltCos = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      const rawThrust = clamp(totalAy / (thrustScale * tiltCos), 0.05, 1.0);
      const thrust = clamp(rawThrust + 0.25 * (rawThrust - uThrust), 0.05, 1.0);

      const estUThrust = 0.7 * uThrust + 0.3 * thrust;
      const bRoll = biasPerThrust.roll * estUThrust + biasResid.roll;
      const bPitch = biasPerThrust.pitch * estUThrust + biasResid.pitch;
      const bYaw = biasPerThrust.yaw * estUThrust + biasResid.yaw;

      const cmdRoll = clamp(desRoll - (bRoll + 22 * simInt.roll + 3.0 * rates.roll) / 65, -0.6, 0.6);
      const cmdPitch = clamp(desPitch - (bPitch + 22 * simInt.pitch + 3.0 * rates.pitch) / 65, -0.6, 0.6);
      const cmdYawRate = clamp(rates.yaw + (-12 * att.yaw - 4.0 * rates.yaw - bYaw) / 8, -2, 2);

      lastAction = { thrust, roll: cmdRoll, pitch: cmdPitch, yawRate: cmdYawRate };
      prevPos = { ...p };
      prevVel = { ...v };
      prevAtt = { ...att };
      prevRates = { ...rates };
      prevDir = { ...dir };
      return lastAction;
    },
  };
}

