        const f = sum * dir[axis] + TASK.linearDrag * (p.baseWind[axis] - s.vel[axis]);
        s.vel[axis] += (f / p.mass - (axis === "y" ? 9.81 : 0)) * dt;
        s.pos[axis] += s.vel[axis] * dt;
      }
      s.t += dt;
      if (s.pos.y <= TASK.bodyHeight) { s.pos.y = TASK.bodyHeight; s.vel.y = Math.max(0, s.vel.y); }
    }
  }
});
