    let prevVel = {...s.vel}, prevAtt = {...s.att}, prevRates = {...s.rates}, prevDir = {x:0, y:1, z:0}, lastAction = {thrust:0.55, roll:0, pitch:0, yawRate:0};
    const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
    const rng = random((101 ^ 0xa5a5a5a5) >>> 0);
    const noise = (n) => (rng() + rng() + rng() - 1.5) * n;
    const vec = (v, n) => Object.fromEntries(Object.entries(v).map(([k, val]) => [k, val + noise(n)]));
    for (let step = 0; step < 350; step++) {
      const obs = { t: +s.t.toFixed(4), pos: vec(s.pos, TASK.positionNoise), vel: vec(s.vel, TASK.velocityNoise), att: vec(s.att, TASK.attitudeNoise), rates: vec(s.rates, TASK.rateNoise) };
      const bx = Math.sin(obs.att.pitch)*Math.cos(obs.att.roll), bz = -Math.sin(obs.att.roll);
      const dir = {x: Math.cos(obs.att.yaw)*bx + Math.sin(obs.att.yaw)*bz, y: Math.cos(obs.att.pitch)*Math.cos(obs.att.roll), z: -Math.sin(obs.att.yaw)*bx + Math.cos(obs.att.yaw)*bz};
      if (step > 0) {
        const alphaM = 1 - Math.exp(-0.005 / 0.038);
        const ut1 = uThrust + (lastAction.thrust - uThrust) * alphaM;
        const ut2 = ut1 + (lastAction.thrust - ut1) * alphaM;
        const effUT = 0.5 * (ut1 + ut2); uThrust = ut2;
        for (const axis of ["roll", "pitch"]) {
          const e1 = lastAction[axis] - prevAtt[axis]; simInt[axis] = clamp(simInt[axis] + e1 * 0.005, -0.35, 0.35);
          const a1 = 65 * e1 - 13 * prevRates[axis] + 22 * simInt[axis]; const ua1 = uAlpha[axis] + (a1 - uAlpha[axis]) * alphaM;
          const midA = 0.5*(prevAtt[axis]+obs.att[axis]), midR = 0.5*(prevRates[axis]+obs.rates[axis]);
          const e2 = lastAction[axis] - midA; simInt[axis] = clamp(simInt[axis] + e2 * 0.005, -0.35, 0.35);
          const a2 = 65 * e2 - 13 * midR + 22 * simInt[axis]; const ua2 = ua1 + (a2 - ua1) * alphaM;
          const effUA = 0.5 * (ua1 + ua2); uAlpha[axis] = ua2;
          if (obs.pos.y > 0.09 && effUT > 0.2) {
            const measA = (obs.rates[axis] - prevRates[axis]) / 0.01 + 0.4 * midR;
            kBias[axis] = clamp(kBias[axis] + 0.18 * (clamp((measA - effUA)/effUT, -45, 45) - kBias[axis]), -45, 45);
          }
        }
        const dragCoeff = 0.0275 * thrustScale;
        const uz = effUT * 0.5 * (prevDir.z + dir.z), vz = 0.5 * (prevVel.z + obs.vel.z);
        const rawWz = clamp((obs.vel.z - prevVel.z)/0.01 + dragCoeff * vz - thrustScale * uz, -16, 16);
        windFast.z += 0.25 * (rawWz - windFast.z);
      }
      const ez = clamp(-0.85 - obs.pos.z, -0.6, 0.6);
      const az = kpZ * ez - kdZ * obs.vel.z + 0.55 * obs.vel.z - windFast.z;
      const desRoll = clamp(Math.atan2(-az, 9.81), -0.5, 0.5);
      const alphaDesR = kpA * (desRoll - obs.att.roll) - kdA * obs.rates.roll;
      const cmdRoll = clamp(obs.att.roll + (alphaDesR - kBias.roll * 0.55 - 22 * simInt.roll + 13.4 * obs.rates.roll) / 65, -0.6, 0.6);
      const act = {thrust: 0.58, roll: cmdRoll, pitch: 0, yawRate: -2 * obs.att.yaw};
      lastAction = act; prevVel = {...obs.vel}; prevAtt = {...obs.att}; prevRates = {...obs.rates}; prevDir = {...dir};
      for (let sub = 0; sub < 2; sub++) {
        const dt = 0.005, inertia = TASK.inertia * p.mass / TASK.baseMass, torque = {};
        for (const axis of ["roll", "pitch"]) {
          const err = act[axis] - s.att[axis]; s.integral[axis] = clamp(s.integral[axis] + err * dt, -0.35, 0.35);
          torque[axis] = inertia * (65 * err - 13 * s.rates[axis] + 22 * s.integral[axis]);
        }
        torque.yaw = inertia * 8 * (act.yawRate - s.rates.yaw);
        const MX = [-1,1,1,-1], MZ = [-1,-1,1,1], SP = [1,-1,1,-1];
        for (let i = 0; i < 4; i++) {
          const des = act.thrust * 4 + torque.roll * MZ[i] / (4 * TASK.arm) - torque.pitch * MX[i] / (4 * TASK.arm) + torque.yaw * SP[i] / (4 * TASK.yawCoefficient);
          const tgt = clamp(des, 0, 4) * (i === p.weakMotor ? 1 - p.weakness : 1);
          s.motors[i] += (tgt - s.motors[i]) * (1 - Math.exp(-dt / p.lag));
        }
        const sum = s.motors.reduce((a,b)=>a+b,0), mom = (sg) => s.motors.reduce((a,f,i)=>a+f*sg[i],0);
        s.rates.roll += (TASK.arm * mom(MZ) / inertia - 0.4 * s.rates.roll) * dt;
        s.rates.pitch += (-TASK.arm * mom(MX) / inertia - 0.4 * s.rates.pitch) * dt;
        s.rates.yaw += (TASK.yawCoefficient * mom(SP) / inertia - 0.4 * s.rates.yaw) * dt;
        for (const axis of ["roll","pitch","yaw"]) s.att[axis] += s.rates[axis] * dt;
        const bx2 = Math.sin(s.att.pitch)*Math.cos(s.att.roll), bz2 = -Math.sin(s.att.roll);
        const dir2 = {x: Math.cos(s.att.yaw)*bx2 + Math.sin(s.att.yaw)*bz2, y: Math.cos(s.att.pitch)*Math.cos(s.att.roll), z: -Math.sin(s.att.yaw)*bx2 + Math.cos(s.att.yaw)*bz2};
        const w = {...p.baseWind}; for (const gst of p.gusts) if (s.t >= gst.start && s.t < gst.start + gst.duration) { w.x += gst.x; w.z += gst.z; }
        for (const axis of ["x","y","z"]) {
          const f = sum * dir2[axis] + TASK.linearDrag * (w[axis] - s.vel[axis]);
          s.vel[axis] += (f / p.mass - (axis === "y" ? 9.81 : 0)) * dt; s.pos[axis] += s.vel[axis] * dt;
        }
        s.t += dt;
      }
    }
    console.log(`Config [${kpA},${kdA},${kpZ},${kdZ}]: t=3.5 dz=${(-0.85-s.pos.z).toFixed(4)} vz=${s.vel.z.toFixed(4)}`);
  }
});
